pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address public constant INITIAL_OWNER = address(0x1234);

    function setUp() public {
        c = new C();
        // Set a known initial owner so we can prank as owner
        vm.prank(address(0));
        c.transferOwnership(INITIAL_OWNER);
    }

    function testFuzz_property(address newOwner) public {
        // The current owner must be INITIAL_OWNER; prank as them
        vm.prank(INITIAL_OWNER);

        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // If call succeeded, owner must be either the previous owner or the newOwner argument.
            // This rules out the bug where owner is always set to address(0).
            address currentOwner = c.owner();
            assertTrue(currentOwner == INITIAL_OWNER || currentOwner == newOwner);
        }
    }
}

