pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // Set initial owner to a known non-zero address (test contract itself)
        // The constructor of C does not set owner, so we do it via a direct pranked call
        // But we need to set owner first. Since constructor does nothing, owner is 0.
        // Anyone can become owner initially? No, transferOwnership checks onlyOwner modifier.
        // We must first become owner. Deploy with owner = address(this) by calling transferOwnership
        // Actually, we can set owner in setUp by deploying a modified version? No.
        // The contract starts with owner = address(0). To call transferOwnership, msg.sender must be owner.
        // So we prank address(0) to call transferOwnership to become owner? No, msg.sender can't be zero.
        // We need to set owner to a non-zero address first. The only way is if we can call transferOwnership as owner.
        // Since owner is 0, no one can satisfy onlyOwner. The contract is stuck.
        // But the diff is about behavior after a successful transferOwnership call.
        // We need to be able to call transferOwnership. We can use vm.prank with the current owner.
        // How to set current owner? The constructor does not set it, so owner == address(0).
        // To make it callable, we can set owner using vm.store? Not allowed.
        // Actually, we can deploy C, then use vm.prank(address(0))? No, msg.sender cannot be zero in a call.
        // The only way is to acknowledge that the test setup must make the contract have an owner.
        // But we cannot change the contract code. However, we can use a helper contract that calls transferOwnership?
        // No, because onlyOwner checks msg.sender.
        // The problem: how to become the initial owner?
        // The contract has no constructor setting owner. So owner is 0. No one can call transferOwnership.
        // But the test must pass on the reference contract for all inputs. If we can't call transferOwnership, the test will revert for all inputs, which is not passing.
        // We must find a way to make the owner non-zero. We can deploy a contract that, in its constructor, does something? No.
        // Wait, we can use vm.prank with the current owner. If owner is 0, we can do vm.prank(address(0))? That might work if foundry allows pranking to 0x0. Many test frameworks do. Let's assume it works.
        vm.prank(address(0));
        c.transferOwnership(address(this)); // now owner = address(this)

        // Now we can call transferOwnership as the owner (address(this))
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        assertTrue(c.owner() == newOwner);
    }
}

